using System;using System.IO;using System.Drawing;using System.Linq;using System.Threading.Tasks;
internal sealed partial class ControlWindow {
 internal async Task RunDataHomeUiSmoke(){try{await Task.Delay(700);string catalog=Common.ReadShared(library.FilePath),sound=Common.ReadShared(AppSettings.FilePath);var ganyu=library.Doc.Items.Single(x=>x.ResourceId=="401000");Require(ganyu.Name=="甘雨","name");Require(library.Doc.Items.Count==10,"actual-baseline card count");foreach(var x in library.Doc.Items){Require(File.Exists(x.SourcePath),"resource absent");using(var im=WallpaperLibrary.LoadCover(x)){Require(im!=null,"persisted cover absent: "+x.Id);}}
  using(var shot=new Bitmap(Width,Height)){DrawToBitmap(shot,new Rectangle(0,0,Width,Height));shot.Save(Path.Combine(Common.Root,"data-home-ui.png"));}
  var op=new ImportOperation(Write);var result=await op.Run("diagnostic",null,null,0,null,null,null,FaultHandoffForm.Demo());var diagnostic=Common.Json.Deserialize<DiagnosticResult>(Common.Json.Serialize(result["diagnostic"]));DiagnosticBundle.Validate(Path.Combine(Common.Root,diagnostic.PackageRelative),diagnostic.Id);using(var zip=System.IO.Compression.ZipFile.OpenRead(Path.Combine(Common.Root,diagnostic.PackageRelative)))using(var reader=new StreamReader(zip.GetEntry("diagnostic.json").Open())){var fields=Common.Obj(Common.Json.Deserialize<System.Collections.Generic.Dictionary<string,object>>(reader.ReadToEnd())["dataLocation"]);Require(Common.S(fields,"dataRoot")==Common.Root&&Common.S(fields,"taskRoot")==Common.WorkRoot,"child location mismatch");}Require(CurrentRun==null&&catalog==Common.ReadShared(library.FilePath)&&sound==Common.ReadShared(AppSettings.FilePath),"UI changed data or played");Common.SaveNew(Path.Combine(Common.Root,"data-home-ui-result.json"),new{passed=true,programRoot=Common.AppRoot,dataRoot=Common.Root,logRoot=Common.LogRoot,taskRoot=Common.WorkRoot,cards=library.Doc.Items.Count,allCoversLoad=true,diagnostic=diagnostic.PackageRelative,workerUsesSameRoot=true,formalCatalogUnchanged=true,settingsUnchanged=true,playbackStarted=false,userClicked=false});
 }catch(Exception ex){Common.SaveNew(Path.Combine(Common.Root,"data-home-ui-result.json"),new{passed=false,error=ex.ToString()});}Close();}
}
#endif
